import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.bIR-4glx.js";const f=JSON.parse('{"title":"第二部：重新学习，打开输入","description":"把自己接住之后，从英语这个具体的训练场重新开始：建立真实基线，让输入经过回忆、表达与反馈，成为能在新场景中使用的能力。","frontmatter":{"title":"第二部：重新学习，打开输入","description":"把自己接住之后，从英语这个具体的训练场重新开始：建立真实基线，让输入经过回忆、表达与反馈，成为能在新场景中使用的能力。","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-1/open-input.md","filePath":"threads/part-1/open-input.md","lastUpdated":1795392000000}'),i={name:"threads/part-1/open-input.md"};function l(p,t,h,n,o,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第二部-重新学习-打开输入" tabindex="-1">第二部：重新学习，打开输入 <a class="header-anchor" href="#第二部-重新学习-打开输入" aria-label="Permalink to &quot;第二部：重新学习，打开输入&quot;">​</a></h1><p>恢复之后，第二件事是重新学习。</p><p>这里有一个容易被忽略的顺序：先恢复容量，再增加负担。一个睡眠破碎、每天只能集中二十分钟的人，不必从最难的教材开始；一个刚被失败打倒的人，也不必用“重新自律”逼自己立刻回到旧节奏。学习可以先很小：今天读一页，明天听十分钟，后天用英语写三句话。</p><p>为什么把英语放在重新学习的第一块训练场？因为它诚实。英语会立刻告诉你哪里没听懂、哪里说不出、哪里只是眼熟。它也有明确的外部标准：一段真实材料、一个真实听众、一封真实邮件。你无法用“我大概懂了”蒙混过关，也不必因为一次失败就否定全部能力。</p><p>这一部把英语当成一个可复制的学习样本：任何新能力都可以经过同样的路径——定义真实任务，保存未经修饰的首版，做有针对性的输入与回忆，接受具体反馈，隔一段时间撤掉提示，换一个条件再做一次。</p><h2 id="本部要回答的问题" tabindex="-1">本部要回答的问题 <a class="header-anchor" href="#本部要回答的问题" aria-label="Permalink to &quot;本部要回答的问题&quot;">​</a></h2><ul><li>我现在在听、说、读、写上分别能完成什么，而不是“总体大概几级”？</li><li>一个词、一段声音或一篇文章，怎样从见过变成能在新场景中使用？</li><li>输入如何经过回忆、表达和反馈，成为不依赖原材料的能力？</li><li>当规则已经见过，结构为什么仍会在真实表达中改变时间、责任、条件或确定性？</li><li>AI 可以在哪一步帮助练习，又必须在哪一步退出，让我独立完成？</li><li>当英语进入求职、面试和远程协作，怎样把等级方向改写成岗位任务与证据？</li></ul><p>不要用最弱的一项否定全部能力，也不要用最强的一项掩盖真实缺口。起点不是判决，而是一张让下一步拥有方向的地图。</p><h2 id="阅读路径" tabindex="-1">阅读路径 <a class="header-anchor" href="#阅读路径" aria-label="Permalink to &quot;阅读路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>章节</th><th>要留下的东西</th></tr></thead><tbody><tr><td>确认起点</td><td><a href="./../part-1/0-cefr">CEFR 目标与英语能力自测</a></td><td>听、说、读、写各一份未经修饰的基线</td></tr><tr><td>建立方法</td><td><a href="./../part-1/1-understanding">认知与训练原则</a> · <a href="./../part-1/2-vocabulary">词汇系统</a> · <a href="./../part-1/grammar">语法篇</a></td><td>一个真实场景、一组可复用词块、一项高影响结构和复测日期</td></tr><tr><td>打开理解</td><td><a href="./../part-1/3-listening">听力训练</a> · <a href="./../part-1/4-reading">阅读训练</a></td><td>主旨重构、困难分类和来源记录</td></tr><tr><td>进入表达</td><td><a href="./../part-1/5-speaking">口语训练</a> · <a href="./../part-1/6-writing">写作训练</a></td><td>首版、反馈、修订版和新条件下的表达</td></tr><tr><td>使用工具</td><td><a href="./../part-1/7-ai">用 AI 学英语</a></td><td>AI 介入边界、独立复测和真实受众反馈</td></tr><tr><td>进入岗位</td><td><a href="./../part-1/8-job-search-english">求职英语篇</a></td><td>岗位语言地图、陌生追问、异步写作和十四天证据</td></tr></tbody></table><p>不用同时推进所有章节。先选择一个会在现实里发生的任务：一次会议、一封邮件、一篇文档、一段说明或一场对话。围绕它打开需要的能力，其余章节先保持安静。</p><h2 id="读完留下什么" tabindex="-1">读完留下什么 <a class="header-anchor" href="#读完留下什么" aria-label="Permalink to &quot;读完留下什么&quot;">​</a></h2><p>这一部结束时，请至少留下三件东西：</p><ol><li>一份能够在三十天后重做的起点样本，包含未经修饰的结构选择；</li><li>一项真实受众能够理解、回应或使用的英语输出；若目标是求职，至少包含一次陌生追问或异步交接；</li><li>一条写明时间、条件和下一变量的<a href="./../../templates/evidence-chain">证据链</a>。</li></ol><p>如果只留下了收藏、播放时长和“学了很多”的感觉，还没有完成这一部。把材料关掉，换一个相近任务，再独立做一次。能力是在提示离开之后仍然存在的部分。</p><h2 id="进入正文" tabindex="-1">进入正文 <a class="header-anchor" href="#进入正文" aria-label="Permalink to &quot;进入正文&quot;">​</a></h2><p>我们先不问自己是否“擅长英语”。先拿出一张纸，保存今天能够完成的版本。</p><p>门不会在准备充分之后才打开。很多时候，是你先伸手推了一下，光才从缝隙里进来。</p>',18)])])}const u=a(i,[["render",l]]);export{f as __pageData,u as default};
